/**
 * 通过UniFFI共享的测量所有者；仅在分析或工作队列上追加、统计和编码。
 */
public protocol PracticeSessionProtocol: AnyObject, Sendable {

    /**
     * 保存当前显示帧为独立命名快照。
     */
