public enum CalibrationState {

    /**
     * 未测。
     */
    case idle
    /**
     * 正在采集。
     */
    case measuring
    /**
     * 检出持续音调，需要确认是环境声。
     */
    case needsQuietConfirmation
    /**
     * 已测。
     */
    case ready
    /**
     * 未成功，旧值在同上下文保留。
     */
    case failed
}


