        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .idle

        case 2: return .measuring

        case 3: return .needsQuietConfirmation

        case 4: return .ready

        case 5: return .failed

        default: throw UniffiInternalError.unexpectedEnumCase
        }
